-- IWANNABERICH: access and RPC hardening
-- Defense in depth: keep direct Data API privileges minimal and bind user-scoped
-- SECURITY DEFINER RPCs to the authenticated identity unless called by service_role.

revoke all on table public.achievements, public.admin_users, public.analytics_events, public.api_rate_limits, public.contribution_events, public.contributions, public.contributor_identities, public.donations, public.growth_attributions, public.growth_events, public.growth_links, public.growth_submissions, public.milestone_events, public.mission_attempts, public.mission_events, public.mission_proofs, public.mission_verifications, public.missions, public.next_experiment_votes, public.notifications, public.participation_actions, public.prediction_rate_limits, public.prediction_votes, public.predictions, public.predictions_comments, public.profiles, public.referral_codes, public.referrals, public.reputation_events, public.reserved_usernames, public.stripe_contributions, public.user_achievements, public.user_private, public.wealth_milestones, public.xp_transactions from anon, authenticated;

grant select on public.achievements to anon, authenticated;
grant select on public.contribution_events, public.contributions, public.contributor_identities, public.mission_proofs, public.mission_verifications, public.notifications, public.referral_codes, public.referrals, public.reputation_events, public.user_private to authenticated;
grant select, insert, update on public.mission_attempts to authenticated;
grant update on public.notifications to authenticated;
grant select, update on public.profiles to authenticated;
grant select on public.missions, public.predictions, public.predictions_comments, public.profiles, public.reserved_usernames, public.user_achievements to anon, authenticated;

create or replace function public.start_mission(p_user_id uuid,p_mission_id uuid) returns public.mission_attempts language plpgsql security definer set search_path to 'public' as $$ declare v_mission public.missions; v_attempt public.mission_attempts; v_service boolean:=coalesce(current_setting('request.jwt.claim.role',true),'')='service_role'; begin if p_user_id is null or (not v_service and p_user_id<>auth.uid()) then raise exception using errcode='42501',message='unauthorized'; end if; select * into v_mission from public.missions where id=p_mission_id and active=true for update; if not found then raise exception using errcode='P0002',message='mission_not_found'; end if; if v_mission.repeat_policy='one_time' then select * into v_attempt from public.mission_attempts where mission_id=p_mission_id and user_id=p_user_id and status in ('started','submitted','under_review','completed') order by created_at desc limit 1; if found then return v_attempt; end if; end if; insert into public.mission_attempts(mission_id,user_id,status) values(p_mission_id,p_user_id,'started') returning * into v_attempt; return v_attempt; exception when unique_violation then select * into v_attempt from public.mission_attempts where mission_id=p_mission_id and user_id=p_user_id and status in ('started','submitted','under_review','completed') order by created_at desc limit 1; if found then return v_attempt; end if; raise; end; $$;

create or replace function public.complete_automatic_mission(p_user_id uuid,p_attempt_id uuid) returns table(attempt public.mission_attempts,xp_awarded integer) language plpgsql security definer set search_path to 'public' as $$ declare v_attempt public.mission_attempts; v_mission public.missions; v_existing public.xp_transactions; v_reward integer; v_service boolean:=coalesce(current_setting('request.jwt.claim.role',true),'')='service_role'; begin if p_user_id is null or (not v_service and p_user_id<>auth.uid()) then raise exception using errcode='42501',message='unauthorized'; end if; select * into v_attempt from public.mission_attempts where id=p_attempt_id and user_id=p_user_id for update; if not found then raise exception using errcode='P0002',message='attempt_not_found'; end if; select * into v_mission from public.missions where id=v_attempt.mission_id and active=true for update; if not found then raise exception using errcode='P0002',message='mission_not_found'; end if; if v_mission.verification_type<>'automatic' then raise exception using errcode='22023',message='automatic_verification_required'; end if; if v_attempt.status='completed' then select * into v_existing from public.xp_transactions where user_id=p_user_id and source_type='mission_completion' and source_id=v_attempt.id limit 1; return query select v_attempt,coalesce(v_existing.amount,0); return; end if; if v_attempt.status not in ('started','submitted') then raise exception using errcode='22023',message='attempt_not_completable'; end if; if v_mission.code='bring_someone_into_experiment' and not exists(select 1 from public.referrals r where r.referrer_id=p_user_id and r.status='qualified') then raise exception using errcode='42501',message='mission_condition_not_met'; end if; v_reward:=v_mission.reward_xp; update public.mission_attempts set status='completed',completed_at=now(),updated_at=now() where id=v_attempt.id returning * into v_attempt; if v_reward>0 then insert into public.xp_transactions(user_id,amount,reason,source_type,source_id,metadata) values(p_user_id,v_reward,'Mission completed: '||v_mission.code,'mission_completion',v_attempt.id,jsonb_build_object('mission_id',v_mission.id,'mission_code',v_mission.code)) on conflict(user_id,source_type,source_id) do nothing; end if; perform public.award_eligible_achievements(p_user_id); return query select v_attempt,v_reward; end; $$;

create or replace function public.verify_mission_proof(p_user_id uuid,p_proof_id uuid,p_decision text,p_reason text default null::text) returns table(proof public.mission_proofs,attempt public.mission_attempts,finalized boolean,xp_awarded integer) language plpgsql security definer set search_path to 'public' as $$ declare v_proof public.mission_proofs; v_attempt public.mission_attempts; v_mission public.missions; v_approvals int; v_rejections int; v_final boolean:=false; v_xp int:=0; v_service boolean:=coalesce(current_setting('request.jwt.claim.role',true),'')='service_role'; begin if p_user_id is null or (not v_service and p_user_id<>auth.uid()) then raise exception using errcode='42501',message='unauthorized'; end if; if p_decision not in ('approve','reject') then raise exception using errcode='22023',message='invalid_decision'; end if; if p_reason is not null and char_length(trim(p_reason))>1000 then raise exception using errcode='22023',message='reason_too_long'; end if; select * into v_proof from public.mission_proofs where id=p_proof_id for update; if not found then raise exception using errcode='P0002',message='proof_not_found'; end if; if v_proof.user_id=p_user_id then raise exception using errcode='42501',message='self_verification_forbidden'; end if; if v_proof.status<>'pending' then raise exception using errcode='22023',message='proof_not_pending'; end if; select * into v_attempt from public.mission_attempts where id=v_proof.attempt_id for update; if not found then raise exception using errcode='P0002',message='attempt_not_found'; end if; select * into v_mission from public.missions where id=v_attempt.mission_id for update; if not found then raise exception using errcode='P0002',message='mission_not_found'; end if; if v_mission.verification_type<>'community' then raise exception using errcode='22023',message='community_verification_required'; end if; if exists(select 1 from public.mission_verifications where proof_id=p_proof_id and verifier_id=p_user_id) then raise exception using errcode='23505',message='already_verified'; end if; insert into public.mission_verifications(proof_id,verifier_id,decision,reason) values(p_proof_id,p_user_id,p_decision,nullif(trim(coalesce(p_reason,'')),'')); select count(*) filter(where decision='approve'),count(*) filter(where decision='reject') into v_approvals,v_rejections from public.mission_verifications where proof_id=p_proof_id; if v_approvals>=3 or v_rejections>=3 then v_final:=true; if v_approvals>=3 then update public.mission_proofs set status='approved' where id=p_proof_id returning * into v_proof; update public.mission_attempts set status='completed',completed_at=now(),updated_at=now() where id=v_attempt.id returning * into v_attempt; v_xp:=v_mission.reward_xp; if v_xp>0 then insert into public.xp_transactions(user_id,amount,reason,source_type,source_id,metadata) values(v_attempt.user_id,v_xp,'Mission completed: '||v_mission.code,'mission_completion',v_attempt.id,jsonb_build_object('mission_id',v_mission.id,'verification','community')) on conflict(user_id,source_type,source_id) do nothing; end if; perform public.award_eligible_achievements(v_attempt.user_id); else update public.mission_proofs set status='rejected' where id=p_proof_id returning * into v_proof; update public.mission_attempts set status='rejected',updated_at=now() where id=v_attempt.id returning * into v_attempt; end if; insert into public.mission_events(user_id,mission_id,attempt_id,event_type,metadata) values(v_attempt.user_id,v_mission.id,v_attempt.id,case when v_approvals>=3 then 'proof_approved' else 'proof_rejected' end,jsonb_build_object('proof_id',p_proof_id,'approvals',v_approvals,'rejections',v_rejections)); insert into public.notifications(user_id,type,title,body,data) values(v_attempt.user_id,'mission',case when v_approvals>=3 then 'Mission verified' else 'Mission rejected' end,case when v_approvals>=3 then 'Your proof was approved.' else 'Your proof was rejected.' end,jsonb_build_object('attempt_id',v_attempt.id,'proof_id',p_proof_id)); end if; return query select v_proof,v_attempt,v_final,v_xp; end; $$;

create or replace function public.submit_growth_mention(p_user_id uuid,p_platform text,p_url text,p_description text) returns uuid language plpgsql security definer set search_path to 'public' as $$ declare v_id uuid; begin if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then raise exception 'forbidden' using errcode='42501'; end if; if p_user_id is null or p_platform is null or length(trim(p_platform)) not between 1 and 80 or p_url is null or length(trim(p_url)) not between 8 and 2048 or p_description is null or length(trim(p_description)) not between 10 and 1000 then raise exception 'invalid_submission' using errcode='22023'; end if; if lower(trim(p_url)) not like 'http://%' and lower(trim(p_url)) not like 'https://%' then raise exception 'invalid_url' using errcode='22023'; end if; insert into public.growth_submissions(user_id,platform,url,description) values(p_user_id,trim(p_platform),trim(p_url),trim(p_description)) on conflict(user_id,url) do update set platform=excluded.platform,description=excluded.description,status='pending',review_reason=null,reviewed_by=null,reviewed_at=null returning id into v_id; return v_id; end; $$;

create or replace function public.review_growth_submission(p_submission_id uuid,p_decision text,p_reason text default null::text) returns boolean language plpgsql security definer set search_path to 'public' as $$ declare v_user uuid; v_status text; v_is_service_role boolean:=coalesce(current_setting('request.jwt.claim.role',true),'')='service_role'; begin if not v_is_service_role and not exists(select 1 from public.admin_users where user_id=auth.uid()) then raise exception 'forbidden' using errcode='42501'; end if; if p_decision not in ('approve','reject') then raise exception 'invalid_decision' using errcode='22023'; end if; if p_reason is not null and length(p_reason)>1000 then raise exception 'invalid_reason' using errcode='22023'; end if; select user_id,status into v_user,v_status from public.growth_submissions where id=p_submission_id for update; if v_user is null then raise exception 'submission_not_found' using errcode='P0002'; end if; if v_status<>'pending' then return false; end if; update public.growth_submissions set status=case when p_decision='approve' then 'approved' else 'rejected' end,review_reason=p_reason,reviewed_by=case when v_is_service_role then null else auth.uid() end,reviewed_at=now() where id=p_submission_id; if p_decision='approve' then perform public.award_achievement_to_user(v_user,'growth_agent',jsonb_build_object('source','external_mention','submission_id',p_submission_id)); perform public.record_growth_event(v_user,'external_mention','The experiment was mentioned on the internet.','An external mention was verified by the team.'); end if; return true; end; $$;
